; bands.asm -- chapter 21: every name 0, in multicolour
; generated by gen21.py
        INCLUDE "msx.inc"
        OUTPUT "bands.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; Multicolour with every one of the 768 names 0: each row of the screen shows
; two of pattern 0's eight bytes, the two its row picks, counted in fours.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $88          ; 16 KB, M2: multicolour, display off
        VDP_REG 0, $00          ; mode: M3 = 0
        VDP_REG 2, $02          ; names    $0800
        VDP_REG 3, $00          ; no colour table in multicolour
        VDP_REG 4, $00          ; patterns $0000
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; backdrop white (15)
        VRAM_WRITE $0800        ; 768 names, all 0
        ld bc, 768
nm:     xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, nm
        VRAM_WRITE $0000        ; pattern 0: four pairs of bytes
        ld hl, pattern
        ld b, 8
        ld c, VDP_DATA
        otir
        VRAM_WRITE $1B00        ; the sprite attribute table ends at once
        ld a, $D0
        out (VDP_DATA), a
shown:  VDP_REG 1, $C8          ; the display on
done:   jr done
pattern:
        db $14, $41, $3F, $F3, $11, $44, $1F, $4F
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
